// catalog.json is the source; the browser bundle is a deterministic generated mirror.
const fs = require("node:fs"),
  path = require("node:path");
const data = JSON.parse(
  fs.readFileSync(path.join(__dirname, "catalog.json"), "utf8"),
);
fs.writeFileSync(
  path.join(__dirname, "catalog-data.js"),
  "// Generated by industrial/build-data.cjs from catalog.json.\n(function(root){const data=" +
    JSON.stringify(data, null, 2) +
    ';if(typeof module!=="undefined")module.exports=data;else root.mapGameIndustrialData=data;})(typeof window!=="undefined"?window:globalThis);\n',
);
